<form method="post" action="<?=url('panel/publicar')?>" enctype="multipart/form-data" class="card"><input type="hidden" name="t" value="<?=csrf()?>"><h3>Publicar producto</h3><label>Nombre<input name="name" required></label><label>Descripción<textarea name="description" required></textarea></label><label>Categoría<select name="cat"><?php foreach($cats as $c)echo '<option value="'.$c['id'].'">'.e($c['name']).'</option>';?></select></label><label>Precio (S/)<input type="number" step="0.01" name="price" required></label><label>Stock<input type="number" name="stock" value="1" min="0"></label><label>Foto<input type="file" name="image" accept="image/*"></label><button class="btn">Publicar producto</button></form>
